// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";

/// @title CertificateValidatedDB - A database driver with certificate-based auth
/// @notice Implements X.509-style certificate chain validation for write access
contract CertificateValidatedDB is Ownable {
    using ECDSA for bytes32;

    struct Certificate {
        address subject;
        address issuer;
        uint256 validFrom;
        uint256 validUntil;
        bytes32 publicKeyHash;
        uint8 pathLenConstraint;
        bool isCA;
    }

    struct AuditEntry {
        address caller;
        bytes32 operationHash;
        uint256 timestamp;
        bool certificateValid;
    }

    mapping(bytes32 => Certificate) public certificates;
    mapping(bytes32 => bytes) public dataStore;
    mapping(bytes32 => bool) public revokedCerts;
    mapping(address => uint256) public nonces;
    AuditEntry[] public auditLog;

    bytes32 public rootCertHash;
    uint256 public constant MAX_CHAIN_DEPTH = 5;
    uint256 public constant CLOCK_SKEW_TOLERANCE = 300; // 5 minutes

    event DataWritten(bytes32 indexed key, address indexed writer, uint256 timestamp);
    event CertificateRegistered(bytes32 indexed certHash, address indexed subject);
    event AuditLogged(uint256 indexed entryId, address indexed caller, bool valid);

    constructor(bytes32 _rootCertHash, Certificate memory _rootCert) {
        rootCertHash = _rootCertHash;
        certificates[_rootCertHash] = _rootCert;
    }

    function registerCertificate(
        bytes32 certHash,
        Certificate memory cert,
        bytes memory issuerSignature
    ) external {
        require(cert.validFrom <= block.timestamp + CLOCK_SKEW_TOLERANCE, "Cert not yet valid");
        require(cert.validUntil >= block.timestamp, "Cert expired");
        require(!revokedCerts[certHash], "Cert revoked");

        // Verify issuer signed this certificate.
        // Bind to this contract and chain id to prevent cross-contract/cross-chain replay.
        bytes32 messageHash = keccak256(
            abi.encodePacked(
                certHash,
                cert.subject,
                cert.validUntil,
                address(this),
                block.chainid
            )
        );
        bytes32 ethSignedHash = messageHash.toEthSignedMessageHash();
        address recoveredIssuer = ethSignedHash.recover(issuerSignature);
        require(recoveredIssuer == cert.issuer, "Invalid issuer signature");

        certificates[certHash] = cert;
        emit CertificateRegistered(certHash, cert.subject);
    }

    /// @notice Validates a certificate chain from leaf to root
    /// @param chainHashes Array of cert hashes from leaf to root
    /// @return isValid Whether the entire chain is valid
    function validateCertificateChain(
        bytes32[] memory chainHashes
    ) public view returns (bool isValid) {
        if (chainHashes.length == 0 || chainHashes.length > MAX_CHAIN_DEPTH) {
            return false;
        }

        // Check that chain terminates at trusted root
        if (chainHashes[chainHashes.length - 1] != rootCertHash) {
            return false;
        }

        uint8 currentPathLen = 0;

        for (uint256 i = 0; i < chainHashes.length; i++) {
            Certificate memory cert = certificates[chainHashes[i]];

            // Check temporal validity
            if (cert.validFrom > block.timestamp + CLOCK_SKEW_TOLERANCE) {
                return false;
            }
            if (cert.validUntil < block.timestamp) {
                return false;
            }

            // Check revocation
            if (revokedCerts[chainHashes[i]]) {
                return false;
            }

            // For non-leaf certs, verify CA status and path length
            if (i < chainHashes.length - 1) {
                // Verify chain linkage: cert[i].issuer == cert[i+1].subject
                Certificate memory issuerCert = certificates[chainHashes[i + 1]];
                if (cert.issuer != issuerCert.subject) {
                    return false;
                }

                // ALL intermediate certs must be CA
                if (i > 0 && !cert.isCA) {
                    return false;
                }
            }

            // Issuer CA status check - the cert that ISSUES must be a CA
            if (i > 0) {
                Certificate memory parentCert = certificates[chainHashes[i]];
                if (!parentCert.isCA) {
                    return false;
                }
            }

            // Path length constraint validation
            if (cert.isCA && i > 0) {
                if (currentPathLen >= cert.pathLenConstraint) {
                    return false;
                }
                currentPathLen++;
            }
        }

        return true;
    }

    /// @notice Write data with certificate-based authorization
    function writeData(
        bytes32 key,
        bytes memory value,
        bytes32[] memory certChain,
        bytes memory signature
    ) external {
        // Guard against empty chains before indexing certChain[0].
        require(certChain.length > 0, "Empty certificate chain");

        // Consume the caller's current nonce to prevent signature replay,
        // and bind the signed payload to this contract and chain id.
        uint256 currentNonce = nonces[msg.sender];

        // Verify the caller signed the operation
        bytes32 opHash = keccak256(
            abi.encodePacked(
                key,
                value,
                currentNonce,
                msg.sender,
                address(this),
                block.chainid
            )
        );
        bytes32 ethSignedOp = opHash.toEthSignedMessageHash();
        address signer = ethSignedOp.recover(signature);

        // Validate certificate chain
        bool chainValid = validateCertificateChain(certChain);

        // Verify signer matches leaf certificate subject
        Certificate memory leafCert = certificates[certChain[0]];
        bool signerMatchesLeaf = (signer == leafCert.subject);

        // Audit logging - always log regardless of outcome
        _logAudit(msg.sender, opHash, chainValid && signerMatchesLeaf);

        // Authorization gate
        require(chainValid, "Invalid certificate chain");
        require(signerMatchesLeaf, "Signer does not match certificate");

        // Invalidate the used nonce to prevent replay.
        nonces[msg.sender] = currentNonce + 1;

        dataStore[key] = value;
        emit DataWritten(key, msg.sender, block.timestamp);
    }

    function _logAudit(address caller, bytes32 opHash, bool valid) internal {
        auditLog.push(AuditEntry({
            caller: caller,
            operationHash: opHash,
            timestamp: block.timestamp,
            certificateValid: valid
        }));
        emit AuditLogged(auditLog.length - 1, caller, valid);
    }

    function revokeCertificate(bytes32 certHash) external onlyOwner {
        revokedCerts[certHash] = true;
    }

    function getAuditLogLength() external view returns (uint256) {
        return auditLog.length;
    }
}
